def kw_for(text):
    out=[]
    for k,v in KW.items():
        if k in text or any(w in text for w in v.split()): out.append(k+' '+v)
    return ' '.join(out)
def match_old(cat, desc):
    cands = {k:v for k,v in old.items() if int(k.split('-')[0])==cat}
    best=None; bs=0
    for k,(d,s,st) in cands.items():
        r=difflib.SequenceMatcher(None, desc, d).ratio()
        if r>bs: bs=r; best=(k,d,s)
    return best if bs>=0.55 else None

