wb=Workbook(); hdr=PatternFill('solid',fgColor='1B5E3C'); hf=Font(bold=True,color='FFFFFF')
def sheet(name, rows, widths=None):
    ws=wb.create_sheet(name)
    if not rows: return ws
    cols=list(rows[0].keys()); ws.append(cols)
    for c_ in ws[1]: c_.fill=hdr; c_.font=hf; c_.alignment=Alignment(vertical='center')
    for r in rows: ws.append([r[k] for k in cols])
    for i,k in enumerate(cols,1):
        ws.column_dimensions[get_column_letter(i)].width=(widths or {}).get(k, min(60, max(10, max(len(str(r[k])) for r in rows)//2+4)))
    ws.freeze_panes='A2'
    return ws
ws=wb.active; ws.title='설정'; ws.append(['키','값','설명'])
for c_ in ws[1]: c_.fill=hdr; c_.font=hf
for k,v,d in settings: ws.append([k,v,d])
ws.column_dimensions['A'].width=22; ws.column_dimensions['B'].width=40; ws.column_dimensions['C'].width=40
